/**
 * Executable fixture tests for the Release Please configuration in this
 * repository.
 *
 * The tests drive the real `release-please` manifest, node strategy and
 * updaters against an in-memory GitHub/file stub: no network call is made, no
 * GitHub state is read or written, and no file in the checked-out worktree is
 * modified.
 *
 * Fixture versions are normalised to `0.7.2` in memory, so the suite passes on
 * the current checkout and on a checkout generated by a previous release. The
 * only thing read from the worktree's live version is the no-mutation
 * assertion.
 *
 * Optional: `SYNDROO_RELEASE_FIXTURE_DIR=/path/to/disposable/copy` materialises
 * the generated 0.8.0 release into an already-created disposable copy of the
 * repository. The copy must live outside this worktree.
 */
import assert from "node:assert/strict";
import { execFileSync } from "node:child_process";
import { existsSync } from "node:fs";
import { mkdir, mkdtemp, readFile, realpath, rm, writeFile } from "node:fs/promises";
import { createRequire } from "node:module";
import { tmpdir } from "node:os";
import { dirname, join, resolve, sep } from "node:path";
import { describe, it } from "node:test";
import { fileURLToPath } from "node:url";

import { ROOT } from "./lib/v1-stages.js";

const CONFIG_PATH = "release-please-config.json";
const MANIFEST_PATH = ".release-please-manifest.json";
const TARGET_BRANCH = "main";
const BASELINE_VERSION = "0.7.2";
const RELEASE_VERSION = "0.8.0";
const BASELINE_TAG = "v0.7.2";
// Current `release/v0.7.2` HEAD; the first release is anchored here, not at the
// start of history, because no earlier tag exists.
const BASELINE_SHA = "4bb57531fea9089c8bb31e5456992e1b53924aed";
const RELEASE_SHA = "1111111111111111111111111111111111111111";
const EXPECTED_RELEASE_PLEASE_VERSION = "17.3.0";
const EXPECTED_WORKSPACES = 11;
const DEPENDENCY_SECTIONS = [
  "dependencies",
  "devDependencies",
  "peerDependencies",
  "optionalDependencies",
] as const;

type JsonObject = Record<string, any>;

const requireFromHere = createRequire(import.meta.url);
const releasePlease = requireFromHere("release-please") as any;
const { signoffCommitMessage } = requireFromHere(
  "release-please/build/src/util/signoff-commit-message.js",
) as { signoffCommitMessage: (message: string, user: string) => string };

// Keep the real strategies quiet; behaviour is asserted directly.
releasePlease.setLogger({
  error() {},
  warn() {},
  info() {},
  debug() {},
  trace() {},
});

const config = JSON.parse(
  await readFile(join(ROOT, CONFIG_PATH), "utf8"),
) as JsonObject;
const extraFiles = config.packages["."]["extra-files"] as {
  path: string;
  jsonpath?: string;
  type?: string;
}[];
const genericFiles = extraFiles.filter((entry) => entry.type === "generic");

const rootPackage = JSON.parse(
  await readFile(join(ROOT, "package.json"), "utf8"),
) as { version: string; workspaces: string[] };
const workspacePaths = rootPackage.workspaces;
// Live checkout version, kept only to prove the fixture runs do not mutate it.
const CHECKOUT_VERSION = rootPackage.version;

async function readRepositoryFiles(): Promise<Map<string, string>> {
  const files = new Map<string, string>();
  const read = async (path: string) => {
    files.set(path, await readFile(join(ROOT, path), "utf8"));
  };

  await read(CONFIG_PATH);
  await read(MANIFEST_PATH);
  await read("package.json");
  await read("package-lock.json");
  for (const path of workspacePaths) {
    await read(`${path}/package.json`);
  }
  // Every configured extra file must be present, including the generic
  // provider `src/index.ts` files. A missing entry would silently skip an
  // updater instead of failing.
  for (const entry of extraFiles) {
    await read(entry.path);
  }

  normalizeVersions(files);
  return files;
}

/**
 * Rewrites the fixture baseline to `0.7.2` in memory so the suite is
 * independent of the live checkout version. Only version-bearing fields are
 * touched: package versions, internal `@syndroo/*` ranges, lock mirrors,
 * release manifest and the annotated provider version constants.
 */
function normalizeVersions(files: Map<string, string>): void {
  const normalizePackage = (pkg: JsonObject) => {
    if (pkg.version === CHECKOUT_VERSION) pkg.version = BASELINE_VERSION;
    for (const section of DEPENDENCY_SECTIONS) {
      const deps = pkg[section];
      if (typeof deps !== "object" || deps === null) continue;
      for (const [name, range] of Object.entries(deps)) {
        if (name.startsWith("@syndroo/") && range === CHECKOUT_VERSION) {
          deps[name] = BASELINE_VERSION;
        }
      }
    }
  };

  for (const path of [
    "package.json",
    ...workspacePaths.map((workspace) => `${workspace}/package.json`),
  ]) {
    const content = files.get(path);
    assert.ok(content !== undefined, `expected ${path} to exist`);
    const pkg = JSON.parse(content);
    normalizePackage(pkg);
    files.set(path, JSON.stringify(pkg, null, 2));
  }

  const lock = JSON.parse(files.get("package-lock.json") ?? "");
  if (lock.version === CHECKOUT_VERSION) lock.version = BASELINE_VERSION;
  if (lock.packages[""].version === CHECKOUT_VERSION) {
    lock.packages[""].version = BASELINE_VERSION;
  }
  for (const path of workspacePaths) {
    const entry = lock.packages[path];
    assert.ok(entry !== undefined, `expected lock entry for ${path}`);
    if (entry.version === CHECKOUT_VERSION) entry.version = BASELINE_VERSION;
    for (const section of DEPENDENCY_SECTIONS) {
      const deps = entry[section];
      if (typeof deps !== "object" || deps === null) continue;
      for (const [name, range] of Object.entries(deps)) {
        if (name.startsWith("@syndroo/") && range === CHECKOUT_VERSION) {
          deps[name] = BASELINE_VERSION;
        }
      }
    }
  }
  files.set("package-lock.json", JSON.stringify(lock, null, 2));

  const manifest = JSON.parse(files.get(MANIFEST_PATH) ?? "");
  for (const path of Object.keys(manifest)) {
    if (manifest[path] === CHECKOUT_VERSION) manifest[path] = BASELINE_VERSION;
  }
  files.set(MANIFEST_PATH, JSON.stringify(manifest, null, 2));

  for (const entry of genericFiles) {
    const content = files.get(entry.path);
    assert.ok(content !== undefined, `expected ${entry.path} to exist`);
    files.set(
      entry.path,
      content.replace(
        /(_PROVIDER_VERSION = ")[^"]+(")/gu,
        `$1${BASELINE_VERSION}$2`,
      ),
    );
  }
}

function internalDependencyFields(pkg: JsonObject): [string, string][] {
  const fields: [string, string][] = [];
  for (const section of DEPENDENCY_SECTIONS) {
    const deps = pkg[section];
    if (typeof deps !== "object" || deps === null) continue;
    for (const [name] of Object.entries(deps)) {
      if (name.startsWith("@syndroo/")) fields.push([section, name]);
    }
  }
  return fields;
}

/**
 * Minimal `Scm` stub: file contents come from a Map, commits and tags from
 * arrays, and every real network or write operation throws.
 */
interface ScmOptions {
  commits?: { sha: string; message: string }[];
  tags?: { name: string; sha: string }[];
  openPullRequests?: any[];
  onUpdatePullRequest?: () => void;
}

function createScm(files: Map<string, string>, options: ScmOptions = {}): any {
  const notAllowed = (operation: string) => () => {
    throw new Error(`stubbed SCM must not perform ${operation}`);
  };
  const commits = options.commits ?? [];
  const tags = options.tags ?? [{ name: BASELINE_TAG, sha: RELEASE_SHA }];
  const openPullRequests = options.openPullRequests ?? [];

  return {
    repository: { owner: "Syndroo", repo: "syndroo" },
    async getFileContentsOnBranch(path: string) {
      const content = files.get(path);
      if (content === undefined) {
        throw new releasePlease.Errors.FileNotFoundError(path);
      }
      return {
        path,
        content: Buffer.from(content, "utf8").toString("base64"),
        parsedContent: content,
        mode: "100644",
      };
    },
    async getFileJson(path: string) {
      const content = files.get(path);
      if (content === undefined) {
        throw new releasePlease.Errors.FileNotFoundError(path);
      }
      return JSON.parse(content);
    },
    async *releaseIterator() {
      // No GitHub releases; the baseline is backfilled from a tag or the
      // bootstrap SHA.
    },
    async *tagIterator() {
      for (const tag of tags) yield tag;
    },
    async *mergeCommitIterator() {
      for (const commit of commits) {
        yield { sha: commit.sha, message: commit.message, files: [] };
      }
    },
    async *pullRequestIterator(_branch: string, status = "OPEN") {
      if (status !== "OPEN") return;
      for (const pullRequest of openPullRequests) yield pullRequest;
    },
    async updatePullRequest(_number: number, _pullRequest: any) {
      options.onUpdatePullRequest?.();
      return openPullRequests[0];
    },
    /**
     * Mirrors `GitHub.buildChangeSet` without the network: each real updater is
     * applied in order to the in-memory file map.
     */
    async buildChangeSet(updates: any[], _branch: string) {
      const changes = new Map<string, string>();
      for (const update of updates) {
        const current = files.get(update.path);
        if (current === undefined && !update.createIfMissing) continue;
        const updated = update.updater.updateContent(current);
        if (typeof updated === "string") {
          files.set(update.path, updated);
          changes.set(update.path, updated);
        }
      }
      return changes;
    },
    findFilesByGlobAndRef: async () => [],
    findFilesByGlob: async () => [],
    findFilesByFilename: async () => [],
    findFilesByFilenameAndRef: async () => [],
    findFilesByExtension: async () => [],
    findFilesByExtensionAndRef: async () => [],
    createPullRequest: notAllowed("createPullRequest"),
    getPullRequest: notAllowed("getPullRequest"),
    createRelease: notAllowed("createRelease"),
    commentOnIssue: notAllowed("commentOnIssue"),
    removeIssueLabels: notAllowed("removeIssueLabels"),
    addIssueLabels: notAllowed("addIssueLabels"),
    generateReleaseNotes: notAllowed("generateReleaseNotes"),
    createFileOnNewBranch: notAllowed("createFileOnNewBranch"),
    commitsSince: notAllowed("commitsSince"),
  };
}

interface ReleaseRun {
  manifest: any;
  pullRequests: any[];
  files: Map<string, string>;
  changes: Map<string, string>;
}

async function buildRelease(
  commitMessages: string[],
  options: ScmOptions = {},
): Promise<ReleaseRun> {
  const files = await readRepositoryFiles();
  const scm = createScm(files, {
    ...options,
    commits:
      options.commits ??
      commitMessages.map((message, index) => ({
        sha: `commit-${index}`,
        message,
      })),
  });
  const manifest = await releasePlease.Manifest.fromManifest(scm, TARGET_BRANCH);
  const pullRequests = await manifest.buildPullRequests();
  const changes = new Map<string, string>();
  for (const pullRequest of pullRequests) {
    const pullRequestChanges = await scm.buildChangeSet(
      pullRequest.updates,
      TARGET_BRANCH,
    );
    for (const [path, content] of pullRequestChanges) {
      changes.set(path, content);
    }
  }
  return { manifest, pullRequests, files, changes };
}

function jsonAt(files: Map<string, string>, path: string): any {
  const content = files.get(path);
  assert.ok(content !== undefined, `expected ${path} to exist`);
  return JSON.parse(content);
}

function providerVersion(content: string): string | undefined {
  return /_PROVIDER_VERSION = "([^"]+)"/u.exec(content)?.[1];
}

function assertFullyBumped(files: Map<string, string>, version: string): void {
  const root = jsonAt(files, "package.json");
  assert.equal(root.version, version, "root package.json version");

  const lock = jsonAt(files, "package-lock.json");
  assert.equal(lock.version, version, "package-lock.json version");
  assert.equal(lock.packages[""].version, version, "lock root package version");

  assert.equal(
    workspacePaths.length,
    EXPECTED_WORKSPACES,
    "workspace count in root package.json",
  );

  for (const path of workspacePaths) {
    const pkg = jsonAt(files, `${path}/package.json`);
    assert.equal(pkg.version, version, `${path}/package.json version`);
    assert.equal(lock.packages[path].version, version, `${path} lock version`);

    for (const [section, name] of internalDependencyFields(pkg)) {
      assert.equal(pkg[section][name], version, `${path} ${section} ${name}`);
      assert.equal(
        lock.packages[path][section]?.[name],
        version,
        `package-lock.json ${path} ${section} ${name}`,
      );
    }
  }

  for (const entry of genericFiles) {
    const content = files.get(entry.path);
    assert.ok(content !== undefined, `expected ${entry.path} to exist`);
    assert.equal(providerVersion(content), version, `${entry.path} version`);
  }

  assert.deepEqual(
    jsonAt(files, MANIFEST_PATH),
    { ".": version },
    "release manifest version",
  );
}

function git(cwd: string, args: string[]): string {
  return execFileSync("git", args, {
    cwd,
    encoding: "utf8",
    stdio: ["ignore", "pipe", "pipe"],
  });
}

function checkDcoScript(): string {
  const compiled = fileURLToPath(new URL("./check-dco.js", import.meta.url));
  return existsSync(compiled) ? compiled : join(ROOT, "scripts/check-dco.ts");
}

function runCheckDco(cwd: string, base: string, head: string): number {
  try {
    execFileSync(process.execPath, [checkDcoScript()], {
      cwd,
      encoding: "utf8",
      stdio: ["ignore", "pipe", "pipe"],
      env: { ...process.env, SYNDROO_BASE_SHA: base, SYNDROO_HEAD_SHA: head },
    });
    return 0;
  } catch (error) {
    const status = (error as { status?: number }).status;
    return typeof status === "number" ? status : 1;
  }
}

describe("release automation fixture", () => {
  it("pins release-please 17.3.0 and the real config", async () => {
    assert.equal(releasePlease.VERSION, EXPECTED_RELEASE_PLEASE_VERSION);

    assert.equal(config["release-type"], "node");
    assert.equal(config["bump-minor-pre-major"], true);
    assert.equal(config["bump-patch-for-minor-pre-major"], false);
    assert.equal(config["include-component-in-tag"], false);
    assert.equal(config["include-v-in-tag"], true);
    assert.equal(config["always-update"], true, "recovery always-update");
    assert.equal(config["bootstrap-sha"], BASELINE_SHA, "first-release anchor");
    assert.equal(
      config.signoff,
      "github-actions[bot] <41898282+github-actions[bot]@users.noreply.github.com>",
    );
    assert.deepEqual(Object.keys(config.packages), ["."]);
    assert.equal(config.packages["."].component, "syndroo");
    assert.equal(genericFiles.length, 5, "generic provider files");

    const manifest = jsonAt(await readRepositoryFiles(), MANIFEST_PATH);
    assert.deepEqual(manifest, { ".": BASELINE_VERSION });
  });

  it("loads every configured extra file, including generic providers", async () => {
    const files = await readRepositoryFiles();
    const missing = extraFiles
      .map((entry) => entry.path)
      .filter((path) => !files.has(path));
    assert.deepEqual(missing, [], "extra files missing from the fixture map");
    assert.equal(extraFiles.length, 67);
  });

  it("bumps a fix to 0.7.3", async () => {
    const run = await buildRelease(["fix: keep the retry budget intact"]);
    assert.equal(run.pullRequests.length, 1);
    assert.equal(String(run.pullRequests[0].version), "0.7.3");
    assertFullyBumped(run.files, "0.7.3");
  });

  it("bumps a feat to 0.8.0 and every configured file", async () => {
    const run = await buildRelease(["feat: add the status command"]);
    assert.equal(run.pullRequests.length, 1);
    assert.equal(String(run.pullRequests[0].version), RELEASE_VERSION);
    assertFullyBumped(run.files, RELEASE_VERSION);

    const untouched = extraFiles
      .map((entry) => entry.path)
      .filter((path) => !run.changes.has(path));
    assert.deepEqual(untouched, [], "extra files the updaters did not change");
  });

  it("bumps a breaking feat to 0.8.0 before 1.0", async () => {
    const run = await buildRelease(["feat!: drop the legacy flags"]);
    assert.equal(run.pullRequests.length, 1);
    assert.equal(String(run.pullRequests[0].version), RELEASE_VERSION);
    assertFullyBumped(run.files, RELEASE_VERSION);
  });

  it("bumps a fix with a BREAKING CHANGE footer to 0.8.0", async () => {
    const run = await buildRelease([
      "fix: rework the runtime\n\nBREAKING CHANGE: state layout changed",
    ]);
    assert.equal(run.pullRequests.length, 1);
    assert.equal(String(run.pullRequests[0].version), RELEASE_VERSION);
    assertFullyBumped(run.files, RELEASE_VERSION);
  });

  it("releases nothing for docs, chore, test and refactor", async () => {
    for (const message of [
      "docs: clarify the release guide",
      "chore: refresh fixtures",
      "test: cover the retry budget",
      "refactor: split the status renderer",
    ]) {
      const run = await buildRelease([message]);
      assert.equal(run.pullRequests.length, 0, `${message} must not release`);
      assert.equal(run.changes.size, 0, `${message} must not change files`);
      assert.equal(jsonAt(run.files, "package.json").version, BASELINE_VERSION);
    }
  });

  it("uses the highest bump for mixed commits", async () => {
    const run = await buildRelease([
      "fix: keep the retry budget intact",
      "docs: clarify the release guide",
      "feat: add the status command",
    ]);
    assert.equal(run.pullRequests.length, 1);
    assert.equal(String(run.pullRequests[0].version), RELEASE_VERSION);
    assertFullyBumped(run.files, RELEASE_VERSION);
  });

  it("covers every internal dependency and lock mirror in extra-files", async () => {
    const files = await readRepositoryFiles();
    const configured = new Set<string>(
      extraFiles.map(
        (entry) => `${entry.path}\u0000${entry.jsonpath ?? ""}`,
      ),
    );
    const lock = jsonAt(files, "package-lock.json");

    const expected = new Set<string>();
    const add = (path: string, jsonpath: string) =>
      expected.add(`${path}\u0000${jsonpath}`);
    // The node strategy's own updaters own the root package and lock version;
    // extra-files must cover every workspace and every internal dependency.
    for (const path of workspacePaths) {
      const pkg = jsonAt(files, `${path}/package.json`);
      add(`${path}/package.json`, "$.version");
      add("package-lock.json", `$.packages['${path}'].version`);
      assert.equal(lock.packages[path].version, pkg.version);

      for (const [section, name] of internalDependencyFields(pkg)) {
        add(`${path}/package.json`, `$['${section}']['${name}']`);
        add(
          "package-lock.json",
          `$.packages['${path}']['${section}']['${name}']`,
        );
      }
    }

    const missing = [...expected].filter((entry) => !configured.has(entry));
    assert.deepEqual(
      missing.map((entry) => entry.replace("\u0000", " ")),
      [],
      "extra-files missing entries",
    );
  });

  it("bootstraps the first release from bootstrap-sha when no tag exists", async () => {
    // No tag, no GitHub release: the older feat before the baseline must not be
    // folded into the first release.
    const run = await buildRelease([], {
      tags: [],
      commits: [
        { sha: "newest-fix", message: "fix: keep the retry budget intact" },
        { sha: BASELINE_SHA, message: "chore: baseline release commit" },
        { sha: "older-feat", message: "feat: should not be released" },
      ],
    });

    assert.equal(run.manifest.bootstrapSha, BASELINE_SHA);
    assert.equal(run.pullRequests.length, 1);
    const pullRequest = run.pullRequests[0];
    assert.equal(String(pullRequest.version), "0.7.3");
    assert.ok(
      !String(pullRequest.body).includes("should not be released"),
      "commits older than bootstrap-sha must be excluded",
    );
    assertFullyBumped(run.files, "0.7.3");
  });

  it("releases nothing for a no-tag docs-only change after the baseline", async () => {
    const run = await buildRelease([], {
      tags: [],
      commits: [
        { sha: "newest-docs", message: "docs: clarify the release guide" },
        { sha: BASELINE_SHA, message: "chore: baseline release commit" },
      ],
    });
    assert.equal(run.pullRequests.length, 0);
    assert.equal(run.changes.size, 0);
    assert.equal(jsonAt(run.files, "package.json").version, BASELINE_VERSION);
  });

  it("passes always-update through to the manifest", async () => {
    const run = await buildRelease(["feat: add the status command"]);
    assert.equal(run.manifest.alwaysUpdate, true);
  });

  it("always-update refreshes an unchanged release PR", async () => {
    const first = await buildRelease(["feat: add the status command"]);
    const pullRequest = first.pullRequests[0];
    assert.ok(pullRequest !== undefined);
    const existing = {
      headBranchName: pullRequest.headRefName,
      baseBranchName: TARGET_BRANCH,
      number: 7,
      title: String(pullRequest.title),
      body: String(pullRequest.body),
      labels: [...pullRequest.labels],
    };
    const commits = [{ sha: "commit-0", message: "feat: add the status command" }];

    let updates = 0;
    const updatingScm = createScm(await readRepositoryFiles(), {
      commits,
      openPullRequests: [existing],
      onUpdatePullRequest: () => {
        updates += 1;
      },
    });
    const updating = await releasePlease.Manifest.fromManifest(
      updatingScm,
      TARGET_BRANCH,
    );
    const updated = await updating.createPullRequests();
    assert.equal(updates, 1, "always-update must refresh the unchanged PR");
    assert.equal(updated.length, 1);

    let skipped = 0;
    const skippingScm = createScm(await readRepositoryFiles(), {
      commits,
      openPullRequests: [existing],
      onUpdatePullRequest: () => {
        skipped += 1;
      },
    });
    const skipping = await releasePlease.Manifest.fromManifest(
      skippingScm,
      TARGET_BRANCH,
      CONFIG_PATH,
      MANIFEST_PATH,
      { alwaysUpdate: false },
    );
    const unchanged = await skipping.createPullRequests();
    assert.equal(skipped, 0, "without always-update the unchanged PR is skipped");
    assert.equal(unchanged.length, 0);
  });

  it("tags the 0.8.0 release as v0.8.0 through the real strategy", async () => {
    const run = await buildRelease(["feat: add the status command"]);
    const pullRequest = run.pullRequests[0];
    assert.ok(pullRequest !== undefined);

    const strategies = await run.manifest.getStrategiesByPath();
    const strategy = strategies["."];
    assert.ok(strategy !== undefined);

    const releases = await strategy.buildReleases({
      headBranchName: pullRequest.headRefName,
      baseBranchName: TARGET_BRANCH,
      number: 1,
      sha: "merge-commit-sha",
      title: String(pullRequest.title),
      body: String(pullRequest.body),
      labels: pullRequest.labels,
      files: [...run.changes.keys()],
    });

    assert.equal(releases.length, 1);
    const release = releases[0];
    assert.equal(String(release.tag), "v0.8.0");
    assert.equal(release.name, "v0.8.0");
  });

  it("passes DCO for a release-please signed-off message", async () => {
    const directory = await mkdtemp(join(tmpdir(), "syndroo-dco-"));
    try {
      git(directory, ["init", "-q"]);
      git(directory, ["config", "user.name", "Fixture"]);
      git(directory, ["config", "user.email", "fixture@example.com"]);
      git(directory, ["commit", "-q", "--allow-empty", "-m", "chore: base"]);
      const base = git(directory, ["rev-parse", "HEAD"]).trim();

      const message = signoffCommitMessage(
        "chore(main): release 0.8.0",
        config.signoff,
      );
      assert.match(message, /^Signed-off-by: /mu);
      git(directory, ["commit", "-q", "--allow-empty", "-m", message]);
      const signed = git(directory, ["rev-parse", "HEAD"]).trim();
      assert.equal(runCheckDco(directory, base, signed), 0);

      git(directory, ["commit", "-q", "--allow-empty", "-m", "chore: unsigned"]);
      const unsigned = git(directory, ["rev-parse", "HEAD"]).trim();
      assert.equal(runCheckDco(directory, signed, unsigned), 1);
    } finally {
      await rm(directory, { recursive: true, force: true });
    }
  });

  it("never mutates the checked-out worktree", async () => {
    const pkg = JSON.parse(
      await readFile(join(ROOT, "package.json"), "utf8"),
    ) as { version: string };
    assert.equal(pkg.version, CHECKOUT_VERSION);
  });

  it(
    "materialises the 0.8.0 release into SYNDROO_RELEASE_FIXTURE_DIR",
    { skip: process.env.SYNDROO_RELEASE_FIXTURE_DIR === undefined },
    async () => {
      const fixtureDir = process.env.SYNDROO_RELEASE_FIXTURE_DIR ?? "";
      const requested = resolve(fixtureDir);
      assert.ok(existsSync(requested), `${requested} must already exist`);
      // Resolve symlinks so a link pointing at the live worktree is rejected.
      const target = await realpath(requested);
      const repo = await realpath(ROOT);
      assert.ok(
        target !== repo && !target.startsWith(repo + sep),
        "SYNDROO_RELEASE_FIXTURE_DIR must be a disposable copy outside the worktree",
      );

      const run = await buildRelease(["feat: add the status command"]);
      assert.equal(String(run.pullRequests[0]?.version), RELEASE_VERSION);

      for (const [path, content] of run.changes) {
        const destination = join(target, path);
        await mkdir(dirname(destination), { recursive: true });
        await writeFile(destination, content, "utf8");
      }

      const written = JSON.parse(
        await readFile(join(target, "package.json"), "utf8"),
      ) as { version: string };
      assert.equal(written.version, RELEASE_VERSION);

      const materialised = new Map<string, string>();
      for (const path of run.changes.keys()) {
        materialised.set(path, await readFile(join(target, path), "utf8"));
      }
      assertFullyBumped(materialised, RELEASE_VERSION);
    },
  );
});
